// WCI Scoring & +2-Sigma Anomaly Detection Engine
const quote = $input.item.json.body;
const price = parseFloat(quote.quoted_price);
const histAvg = parseFloat(quote.historical_avg || 5000000);
const stdDev = parseFloat(quote.std_dev || 400000);

// Check +2-sigma threshold
const isAnomaly = price > (histAvg + 2 * stdDev);

// Calculate Weighted Composite Index (WCI)
// WCI = 0.35*(PriceScore) + 0.30*(Quality) + 0.20*(Delivery) + 0.15*(FinancialStability)
const priceScore = Math.max(0, Math.min(100, 100 - ((price - histAvg) / histAvg) * 100));
const quality = parseFloat(quote.quality_score || 90);
const delivery = parseFloat(quote.delivery_score || 90);
const financial = parseFloat(quote.financial_stability_score || 85);

const wci = (0.35 * priceScore) + (0.30 * quality) + (0.20 * delivery) + (0.15 * financial);

return {
  wedding_id: quote.wedding_id || 1,
  category_code: quote.category_code || 'CAT-02',
  category_name: quote.category_name || 'Royal Catering & Banqueting',
  vendor_name: quote.vendor_name,
  quoted_price: price,
  historical_avg: histAvg,
  std_dev: stdDev,
  quality_score: quality,
  delivery_score: delivery,
  financial_stability_score: financial,
  wci_score: parseFloat(wci.toFixed(2)),
  anomaly_flag: isAnomaly,
  status: isAnomaly ? 'rejected' : 'submitted'
};
